package vn.com.apartment.commercial;
import jakarta.persistence.*;
@Entity @Table(name="commercial_parking_vehicles")
public class CommercialParkingVehicle{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="assignment_id")private CommercialServiceAssignment assignment;@Column(name="plate_number",nullable=false,length=30)private String plateNumber;@Column(name="vehicle_type",nullable=false,length=20)private String vehicleType;@Column(name="electric_vehicle",nullable=false)private boolean electricVehicle;@Column(nullable=false)private boolean active=true;protected CommercialParkingVehicle(){}public CommercialParkingVehicle(CommercialServiceAssignment a,String p,String t,boolean e){assignment=a;plateNumber=p;vehicleType=t;electricVehicle=e;}public void deactivate(){active=false;}public Long getId(){return id;}public CommercialServiceAssignment getAssignment(){return assignment;}public String getPlateNumber(){return plateNumber;}public String getVehicleType(){return vehicleType;}public boolean isElectricVehicle(){return electricVehicle;}public boolean isActive(){return active;}}
